/// offer to transfer data
class WlDataOffer extends Proxy {
  WlDataOffer(super.connection, super.id, super.version);

  static const WaylandInterface<WlDataOffer> interface =
      WaylandInterface('wl_data_offer', 4, WlDataOffer.new);

  @override
  String get interfaceName => 'wl_data_offer';

  /// accept one of the offered mime types
  void accept(int serial, String? mimeType) {
    final WireWriter w = WireWriter(id, 0);
    w.uint32(serial);
    w.string(mimeType);
    send(w);
  }

  /// request that the data is transferred
  void receive(String mimeType, RandomAccessFile fd) {
    final WireWriter w = WireWriter(id, 1);
    w.string(mimeType);
    w.fd(fd);
    send(w);
  }

  /// destroy data offer
  void destroy() {
    final WireWriter w = WireWriter(id, 2);
    send(w);
    markDestroyed();
  }

  /// the offer will no longer be used
  ///
  /// Available since version 3.
  void finish() {
    final WireWriter w = WireWriter(id, 3);
    send(w);
  }

  /// set the available/preferred drag-and-drop actions
  ///
  /// Available since version 3.
  void setActions(int dndActions, int preferredAction) {
    final WireWriter w = WireWriter(id, 4);
    w.uint32(dndActions);
    w.uint32(preferredAction);
    send(w);
  }

  /// advertise offered mime type
  void Function(String mimeType)? onOffer;

  /// notify the source-side available actions
  void Function(int sourceActions)? onSourceActions;

  /// notify the selected action
  void Function(int dndAction)? onAction;

  @override
  void dispatchEvent(int opcode, WireReader r) {
    switch (opcode) {
      case 0:
        final _mimeType = r.string() ?? '';
        if (destroyed) return;
        onOffer?.call(_mimeType);
      case 1:
        final _sourceActions = r.uint32();
        if (destroyed) return;
        onSourceActions?.call(_sourceActions);
      case 2:
        final _dndAction = r.uint32();
        if (destroyed) return;
        onAction?.call(_dndAction);
    }
  }
}

/// `wl_data_offer.error`
