  @override
  String get interfaceName => 'wl_data_source';

  /// add an offered mime type
  void offer(String mimeType) {
    final WireWriter w = WireWriter(id, 0);
    w.string(mimeType);
    send(w);
  }

  /// destroy the data source
  void destroy() {
    final WireWriter w = WireWriter(id, 1);
    send(w);
    markDestroyed();
  }

  /// set the available drag-and-drop actions
  ///
  /// Available since version 3.
  void setActions(int dndActions) {
    final WireWriter w = WireWriter(id, 2);
    w.uint32(dndActions);
    send(w);
  }

  /// a target accepts an offered mime type
  void Function(String? mimeType)? onTarget;

  /// send the data
  void Function(String mimeType, RandomAccessFile fd)? onSend;

  /// selection was cancelled
  void Function()? onCancelled;

  /// the drag-and-drop operation physically finished
  void Function()? onDndDropPerformed;

  /// the drag-and-drop operation concluded
  void Function()? onDndFinished;

