        if (destroyed) return;
        onSend?.call(_mimeType, _fd);
      case 2:
        if (destroyed) return;
        onCancelled?.call();
      case 3:
        if (destroyed) return;
        onDndDropPerformed?.call();
      case 4:
        if (destroyed) return;
        onDndFinished?.call();
      case 5:
        final _dndAction = r.uint32();
        if (destroyed) return;
        onAction?.call(_dndAction);
    }
  }
