/// data transfer device
class WlDataDevice extends Proxy {
  WlDataDevice(super.connection, super.id, super.version);

  static const WaylandInterface<WlDataDevice> interface =
      WaylandInterface('wl_data_device', 4, WlDataDevice.new);

  @override
  String get interfaceName => 'wl_data_device';

  /// start drag-and-drop operation
  void startDrag(WlDataSource? source, WlSurface origin, WlSurface? icon, int serial) {
    final WireWriter w = WireWriter(id, 0);
    w.uint32(source?.id ?? 0);
    w.uint32(origin.id);
    w.uint32(icon?.id ?? 0);
    w.uint32(serial);
    send(w);
  }

  /// copy data to the selection
  void setSelection(WlDataSource? source, int serial) {
    final WireWriter w = WireWriter(id, 1);
    w.uint32(source?.id ?? 0);
    w.uint32(serial);
    send(w);
  }

  /// destroy data device
  ///
  /// Available since version 2.
  void release() {
    final WireWriter w = WireWriter(id, 2);
    send(w);
    markDestroyed();
  }

  /// introduce a new wl_data_offer
  void Function(WlDataOffer id_)? onDataOffer;

  /// initiate drag-and-drop session
  void Function(int serial, WlSurface surface, double x, double y, WlDataOffer? id_)? onEnter;

  /// end drag-and-drop session
  void Function()? onLeave;

  /// drag-and-drop session motion
  void Function(int time, double x, double y)? onMotion;

  /// end drag-and-drop session successfully
  void Function()? onDrop;

  /// advertise new selection
  void Function(WlDataOffer? id_)? onSelection;

  @override
  void dispatchEvent(int opcode, WireReader r) {
    switch (opcode) {
      case 0:
        final _id = connection.adoptServerObject(WlDataOffer.new, r.uint32(), version);
        if (destroyed) return;
        onDataOffer?.call(_id);
      case 1:
        final _serial = r.uint32();
        final _surface = connection.lookup(r.uint32()) as WlSurface?;
        final _x = r.fixed();
        final _y = r.fixed();
        final _id = connection.lookup(r.uint32()) as WlDataOffer?;
        if (destroyed) return;
        if (_surface == null) return;
        onEnter?.call(_serial, _surface!, _x, _y, _id);
      case 2:
        if (destroyed) return;
        onLeave?.call();
      case 3:
        final _time = r.uint32();
        final _x = r.fixed();
        final _y = r.fixed();
        if (destroyed) return;
        onMotion?.call(_time, _x, _y);
      case 4:
        if (destroyed) return;
        onDrop?.call();
      case 5:
        final _id = connection.lookup(r.uint32()) as WlDataOffer?;
        if (destroyed) return;
        onSelection?.call(_id);
    }
  }
}

