  @override
  void dispatchEvent(int opcode, WireReader r) {
    switch (opcode) {
      case 0:
        final _serial = r.uint32();
        final _surface = connection.lookup(r.uint32()) as WlSurface?;
        final _surfaceX = r.fixed();
        final _surfaceY = r.fixed();
        if (destroyed) return;
        if (_surface == null) return;
        onEnter?.call(_serial, _surface!, _surfaceX, _surfaceY);
      case 1:
        final _serial = r.uint32();
        final _surface = connection.lookup(r.uint32()) as WlSurface?;
        if (destroyed) return;
        if (_surface == null) return;
        onLeave?.call(_serial, _surface!);
      case 2:
        final _time = r.uint32();
        final _surfaceX = r.fixed();
        final _surfaceY = r.fixed();
        if (destroyed) return;
        onMotion?.call(_time, _surfaceX, _surfaceY);
      case 3:
        final _serial = r.uint32();
        final _time = r.uint32();
        final _button = r.uint32();
        final _state = r.uint32();
        if (destroyed) return;
        onButton?.call(_serial, _time, _button, _state);
      case 4:
        final _time = r.uint32();
        final _axis = r.uint32();
        final _value = r.fixed();
        if (destroyed) return;
        onAxis?.call(_time, _axis, _value);
      case 5:
        if (destroyed) return;
        onFrame?.call();
      case 6:
        final _axisSource = r.uint32();
        if (destroyed) return;
        onAxisSource?.call(_axisSource);
      case 7:
        final _time = r.uint32();
        final _axis = r.uint32();
        if (destroyed) return;
        onAxisStop?.call(_time, _axis);
      case 8:
        final _axis = r.uint32();
        final _discrete = r.int32();
        if (destroyed) return;
        onAxisDiscrete?.call(_axis, _discrete);
      case 9:
        final _axis = r.uint32();
        final _value120 = r.int32();
        if (destroyed) return;
        onAxisValue120?.call(_axis, _value120);
      case 10:
        final _axis = r.uint32();
        final _direction = r.uint32();
        if (destroyed) return;
        onAxisRelativeDirection?.call(_axis, _direction);
      case 11:
        final _surfaceX = r.fixed();
        final _surfaceY = r.fixed();
        if (destroyed) return;
        onWarp?.call(_surfaceX, _surfaceY);
